test("matrix: annualization deterministic across large range", () => {
  for (const testCase of ANNUALIZATION_CASES) {
    assert.equal(annualizeMonthlyValue(testCase.monthlyUsd), testCase.expectedAnnualUsd, testCase.id);
  }
});

test("matrix: monthly margin deterministic across positive and negative profits", () => {
  for (const testCase of MARGIN_CASES) {
    const actual = computeMonthlyMarginPercent(testCase.monthlyProfitUsd, testCase.monthlyBillingUsd);
    assert.ok(
      Math.abs(actual - testCase.expectedPercent) < 0.000000000001,
      `${testCase.id}: expected=${testCase.expectedPercent} actual=${actual}`
    );
  }
});

test("matrix: cycle coverage deterministic", () => {
  for (const testCase of CYCLE_CASES) {
    const months = computeMonthsToCoverModules(testCase.totalModules, testCase.monthlyModules);
    assert.equal(months, testCase.expectedMonths, `${testCase.id}: months`);

    const points = buildCycleWidgetPoints({
      totalModules: testCase.totalModules,
      monthlyModules: testCase.monthlyModules,
      monthsToProject: months
    });

    assert.equal(points.length, months, `${testCase.id}: points length`);
    const tail = points[points.length - 1];
    assert.ok(tail, `${testCase.id}: tail exists`);
    assert.equal(tail?.modulesServicedThisMonth, testCase.expectedTail, `${testCase.id}: expected tail modules`);
    assert.equal(tail?.remainingModulesInCycle, 0, `${testCase.id}: remaining modules should be 0`);
    assert.equal(tail?.cycleCompleted, true, `${testCase.id}: cycle must complete`);
  }
});

test("edge cases: zeros and negatives", () => {
  assert.equal(computeMonthsToCoverModules(0, 12), 0);
  assert.equal(computeMonthsToCoverModules(-1, 12), 0);
  assert.equal(computeMonthsToCoverModules(100, 0), 0);

  assert.equal(buildCycleWidgetPoints({ totalModules: 0, monthlyModules: 12, monthsToProject: 35 }).length, 0);
  assert.equal(buildCycleWidgetPoints({ totalModules: 100, monthlyModules: 0, monthsToProject: 35 }).length, 0);
  assert.equal(buildCycleWidgetPoints({ totalModules: 100, monthlyModules: 12, monthsToProject: 0 }).length, 0);

  const kpis = buildIndustrialKpis({
    totalModules: 0,
    monthlyModules: 0,
    monthlyBillingUsd: 0,
    monthlyProfitUsd: -100,
    annualProfitUsd: -1200
  });

  assert.equal(kpis.monthlyProfitUsd, -100);
  assert.equal(kpis.annualProfitUsd, -1200);
  assert.equal(normalizePitchText("  alpha\n beta\t gamma  "), "alpha beta gamma");
});

